import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;

public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class Rectangle {
        long x1, y1, x2, y2;

        Rectangle(long x1, long y1, long x2, long y2) {
            this.x1 = Math.min(x1, x2);
            this.x2 = Math.max(x1, x2);
            this.y1 = Math.min(y1, y2);
            this.y2 = Math.max(y1, y2);
        }

        long distanceTo(Rectangle other) {
            long dx = 0;
            if (this.x2 < other.x1) {
                dx = other.x1 - this.x2;
            } else if (other.x2 < this.x1) {
                dx = this.x1 - other.x2;
            }

            long dy = 0;
            if (this.y2 < other.y1) {
                dy = other.y1 - this.y2;
            } else if (other.y2 < this.y1) {
                dy = this.y1 - other.y2;
            }

            return dx + dy;
        }
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        String firstToken = sc.next();
        if (firstToken == null) return;

        long xi = Long.parseLong(firstToken);
        long yi = sc.nextInt();
        long xf = sc.nextInt();
        long yf = sc.nextInt();

        int n = sc.nextInt();

        int totalVertices = n + 2;
        Rectangle[] rects = new Rectangle[totalVertices];

        // Vértice 0: Ponto inicial
        rects[0] = new Rectangle(xi, yi, xi, yi);

        // Vértices 1 a N: Áreas cobertas
        for (int i = 1; i <= n; i++) {
            long x1 = sc.nextInt();
            long y1 = sc.nextInt();
            long x2 = sc.nextInt();
            long y2 = sc.nextInt();
            rects[i] = new Rectangle(x1, y1, x2, y2);
        }

        // Vértice N + 1: Ponto final
        rects[n + 1] = new Rectangle(xf, yf, xf, yf);

        // Algoritmo de Dijkstra O(V^2)
        long[] dist = new long[totalVertices];
        boolean[] visited = new boolean[totalVertices];
        Arrays.fill(dist, Long.MAX_VALUE);

        dist[0] = 0;

        for (int i = 0; i < totalVertices; i++) {
            int u = -1;
            long minDist = Long.MAX_VALUE;

            for (int v = 0; v < totalVertices; v++) {
                if (!visited[v] && dist[v] < minDist) {
                    minDist = dist[v];
                    u = v;
                }
            }

            if (u == -1 || minDist == Long.MAX_VALUE) {
                break;
            }

            if (u == n + 1) {
                break; // Chegamos ao destino
            }

            visited[u] = true;

            for (int v = 0; v < totalVertices; v++) {
                if (!visited[v]) {
                    long weight = rects[u].distanceTo(rects[v]);
                    if (dist[u] + weight < dist[v]) {
                        dist[v] = dist[u] + weight;
                    }
                }
            }
        }

        System.out.println(dist[n + 1]);
    }
}
